# Unique items get the shapes locations have: their points become point geometries.
def points_to_geometry(apps, schema_editor):
    for position in apps.get_model("maps", "UniqueItemPosition").objects.all():
        position.geometry, position.kind = position.point, "point"
        position.save(update_fields=["geometry", "kind"])


def geometry_to_points(apps, schema_editor):
    # Back to points: rectangles and areas by their centre, positions without one go.
    for position in apps.get_model("maps", "UniqueItemPosition").objects.all():
        if position.geometry is None:
            position.delete()
            continue
        position.point = position.geometry if position.geometry.geom_type == "Point" else position.geometry.centroid
        position.save(update_fields=["point"])


